'use strict';
const MAP_CACHE='atlas-ukraine-roads-20260921-z11-v1';
class ChunkedMapSource {
 constructor(manifest){this.manifest=manifest;this.pending=new Map();this.memory=new Map()}
 getKey(){return 'ukraine-'+this.manifest.version}
 async chunk(index){if(this.memory.has(index))return this.memory.get(index);if(this.pending.has(index))return this.pending.get(index);const request=(async()=>{const url=new URL(`map/part-${String(index).padStart(3,'0')}.bin`,location.href).href;let cache;try{cache=await caches.open(MAP_CACHE)}catch{}let response=cache&&await cache.match(url),fromCache=!!response;if(!response){response=await fetch(url);if(!response.ok)throw new Error('离线地图数据读取失败')}const bytes=await response.arrayBuffer();const expected=this.manifest.parts[index];if(bytes.byteLength!==expected.size){if(cache)await cache.delete(url);throw new Error('地图数据不完整，请重试')}if(crypto.subtle){const digest=await crypto.subtle.digest('SHA-256',bytes),hash=[...new Uint8Array(digest)].map(v=>v.toString(16).padStart(2,'0')).join('');if(hash!==expected.sha256){if(cache)await cache.delete(url);throw new Error('地图校验失败，请重试')}}if(cache&&!fromCache)try{await cache.put(url,new Response(bytes,{headers:{'Content-Type':'application/octet-stream'}}))}catch{};this.memory.set(index,bytes);if(this.memory.size>12)this.memory.delete(this.memory.keys().next().value);return bytes})();this.pending.set(index,request);try{return await request}finally{this.pending.delete(index)}}
 async getBytes(offset,length){const size=this.manifest.chunkSize,start=Math.floor(offset/size),end=Math.floor((offset+length-1)/size),out=new Uint8Array(length);for(let i=start;i<=end;i++){const b=new Uint8Array(await this.chunk(i)),lo=Math.max(offset,i*size),hi=Math.min(offset+length,(i+1)*size);out.set(b.subarray(lo-i*size,hi-i*size),lo-offset)}return {data:out.buffer}}
}
window.setupOfflineMap=async function(map){const response=await fetch('map/manifest.json');if(!response.ok)throw new Error('地图清单加载失败');const manifest=await response.json();const source=new ChunkedMapSource(manifest),archive=new pmtiles.PMTiles(source);const makeBase=()=>protomapsL.leafletLayer({url:archive,flavor:'light',lang:window.atlasI18n?.language==='uk'?'uk':'en',maxDataZoom:manifest.maxZoom,levelDiff:1,maxZoom:19,attribution:'© <a href="https://www.openstreetmap.org/copyright" target="_blank">OpenStreetMap</a> · <a href="https://protomaps.com" target="_blank">Protomaps</a>'}).addTo(map);let base=makeBase();let online=null,onlineFailed=false;map.createPane('onlineBase');map.getPane('onlineBase').style.zIndex=220;const select={value:'auto'},status={textContent:''},button=document.getElementById('save-offline'),progress=document.getElementById('offline-progress');let loadingOnline=false;const update=async()=>{const center=map.getCenter(),outside=center.lng<22||center.lng>40.5||center.lat<44||center.lat>52.5;const want=select.value==='auto'&&navigator.onLine&&(map.getZoom()>=14||outside);if(!want){if(online&&map.hasLayer(online))map.removeLayer(online);status.textContent='内置道路与城市底图 · English';return}status.textContent=onlineFailed?'在线细节不可用 · 内置底图':'在线建筑细节 · English';if(onlineFailed||loadingOnline)return;if(!online){loadingOnline=true;try{const res=await fetch('online-style.json');if(!res.ok)throw new Error('style');online=L.maplibreGL({style:localizeMapStyle(await res.json()),interactive:false,pane:'onlineBase',attribution:'<a href="https://openfreemap.org">OpenFreeMap</a> © <a href="https://openmaptiles.org">OpenMapTiles</a> © <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'});}catch{onlineFailed=true;status.textContent='在线细节不可用 · 内置底图'}finally{loadingOnline=false}}if(online&&select.value==='auto'&&navigator.onLine&&(map.getZoom()>=14||outside)&&!map.hasLayer(online)){online.addTo(map);const gl=online.getMaplibreMap();gl.on('error',()=>{onlineFailed=true;if(map.hasLayer(online))map.removeLayer(online);status.textContent='在线细节不可用 · 内置底图'})}};select.onchange=update;map.on('moveend',update);window.addEventListener('online',()=>{onlineFailed=false;update()});window.addEventListener('offline',update);window.addEventListener('atlaslanguagechange',()=>{map.removeLayer(base);base=makeBase();if(online&&map.hasLayer(online))map.removeLayer(online);online=null;onlineFailed=false;update();});update();
let serviceReady=false;try{if('serviceWorker'in navigator){await navigator.serviceWorker.register('./sw.js');await Promise.race([navigator.serviceWorker.ready,new Promise((_,reject)=>setTimeout(()=>reject(new Error('Offline setup timeout')),12000))]);serviceReady=true}}catch{}const sizeMB=(manifest.size/1048576).toFixed(0);button.textContent=`保存离线地图（${sizeMB} MB）`;progress.textContent='覆盖乌克兰全境主要道路、城市与地名；保存后可断网使用。更细街巷与建筑需联网。';
async function isComplete(){try{const cache=await caches.open(MAP_CACHE);const keys=await cache.keys();const paths=new Set(keys.map(r=>new URL(r.url).pathname));return manifest.parts.every((_,i)=>paths.has(new URL(`map/part-${String(i).padStart(3,'0')}.bin`,location.href).pathname))}catch{return false}}
if(serviceReady&&await isComplete()){button.textContent='离线地图已保存';progress.textContent='可断网重新打开网站。更细街巷与建筑需联网；清除浏览器数据后需重新保存。'}
button.onclick=async()=>{button.disabled=true;try{if(!serviceReady)throw new Error('当前浏览器尚未启用离线缓存，请刷新后重试。');const estimate=await navigator.storage?.estimate();if(estimate?.quota&&estimate.quota-estimate.usage<manifest.size&&!await isComplete())throw new Error('浏览器可用空间不足，请释放空间后重试。');await navigator.storage?.persist?.();let next=0,done=0;await Promise.all(Array.from({length:3},async()=>{while(next<manifest.parts.length){const i=next++;await source.chunk(i);done++;button.textContent=`正在保存 ${Math.round(done/manifest.parts.length*100)}%`;progress.textContent=`已保存 ${done} / ${manifest.parts.length}，请保持页面打开。`}}));if(!await isComplete())throw new Error('浏览器未能完整保存地图，请重试。');button.textContent='离线地图已保存';progress.textContent='已完整保存道路与城市底图。断网可重新打开；更细街巷与建筑需联网。'}catch(e){button.textContent='继续保存离线地图';progress.textContent=e.message+' 已保存部分可复用。'}finally{button.disabled=false}};return {base,source,archive,manifest}};

function localizeMapStyle(style){if(window.atlasI18n?.language!=='uk')return style;for(const layer of style.layers||[]){const field=layer.layout?.['text-field'];if(Array.isArray(field)&&field[0]==='coalesce'&&JSON.stringify(field).includes('name:en'))layer.layout['text-field']=['coalesce',['get','name:uk'],['get','name_uk'],['get','name'],['get','name:en'],['get','name_en']];}return style}
